describe('Table Row Filtering by Search Input', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should filter table rows by typing in search input and display matching results', () => {
    // Verify initial table state
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Intercept API call to get initial table data
    cy.intercept('GET', '/api/table-data').as('getTableData');
    cy.wait('@getTableData');

    // Verify initial table content
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Type in search input
    cy.get('[data-testid="search-input"]').type('test');

    // Verify search input is focused
    cy.get('[data-testid="search-input"]').should('have.focus');

    // Verify table rows are still visible
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify search input has value
    cy.get('[data-testid="search-input"]').should('have.value', 'test');

    // Wait for API call to filter data
    cy.intercept('GET', '/api/table-data?search=test').as('filterTableData');
    cy.wait('@filterTableData');

    // Verify filtered table rows are displayed
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="table-row"]').should('contain', 'test');

    // Verify table headers are still visible
    cy.get('[data-testid="table-header"]').should('be.visible');

    // Verify search input is still visible
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Verify pagination controls are still visible
    cy.get('[data-testid="pagination-controls"]').should('be.visible');
  });

  it('should handle empty search input and display all table rows', () => {
    // Intercept initial API call
    cy.intercept('GET', '/api/table-data').as('getTableData');
    cy.wait('@getTableData');

    // Verify initial table content
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Clear search input
    cy.get('[data-testid="search-input"]').clear();

    // Verify search input is cleared
    cy.get('[data-testid="search-input"]').should('have.value', '');

    // Verify all table rows are displayed again
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify table headers are still visible
    cy.get('[data-testid="table-header"]').should('be.visible');

    // Verify pagination controls are still visible
    cy.get('[data-testid="pagination-controls"]').should('be.visible');
  });
});
